  "src/iban.js": "// IBAN (ISO 13616 mod-97 over a fixed country table) and Luhn check digits\nconst LENGTHS = { BE: 16, CH: 21, DE: 22, FR: 27, GB: 22, MT: 31, NL: 18, NO: 15 };\nfunction normalize(s) {\n  if (typeof s !== 'string' || !/^[0-9A-Za-z ]*$/.test(s)) return null;\n  const t = s.replace(/ /g, '').toUpperCase();\n  if (!/^[A-Z]{2}\\d{2}[0-9A-Z]+$/.test(t) || LENGTHS[t.slice(0, 2)] !== t.length) return null;\n  const cd = Number(t.slice(2, 4)); if (cd < 2 || cd > 98) return null;\n  let r = 0;\n  for (const ch of t.slice(4) + t.slice(0, 4)) { const v = parseInt(ch, 36); r = (v < 10 ? r * 10 + v : r * 100 + v) % 97; }\n  return r === 1 ? t : null;\n}\nconst isValidIban = (s) => normalize(s) !== null;\nfunction formatIban(s) { const t = normalize(s); if (t === null) throw new RangeError('invalid IBAN'); return t.match(/.{1,4}/g).join(' '); }\nfunction luhnCheck(s) {\n  if (typeof s !== 'string') throw new TypeError('luhnCheck: expected a string');\n  if (!/^\\d{2,}$/.test(s)) return false;\n  let sum = 0;\n  for (let i = 0; i < s.length; i++) { let d = s.charCodeAt(s.length - 1 - i) - 48; if (i % 2 === 1) { d *= 2; if (d > 9) d -= 9; } sum += d; }\n  return sum % 10 === 0;\n}\nmodule.exports = { isValidIban, formatIban, luhnCheck };\n",
  "src/wrap.js": "// greedy word wrap and full justification\nfunction check(text, width) {\n  if (typeof text !== 'string') throw new TypeError('text must be a string');\n  if (!Number.isInteger(width) || width < 1) throw new RangeError('width must be a positive integer');\n}\nfunction wrapText(text, width) {\n  check(text, width);\n  const lines = []; let line = '';\n  for (let w of text.split(/[ \\t\\r\\n]+/).filter(Boolean)) {\n    if (line && line.length + 1 + w.length <= width) { line += ` ${w}`; continue; }\n    if (line) lines.push(line);\n    while (w.length > width) { lines.push(w.slice(0, width)); w = w.slice(width); }\n    line = w;\n  }\n  if (line) lines.push(line);\n  return lines;\n}\nfunction justify(text, width) {\n  const lines = wrapText(text, width);\n  return lines.map((l, i) => {\n    const ws = l.split(' '); if (i === lines.length - 1 || ws.length === 1) return l;\n    const gaps = ws.length - 1; const spaces = width - l.length + gaps; const base = Math.floor(spaces / gaps); const extra = spaces % gaps;\n    return ws.reduce((acc, w, j) => `${acc}${' '.repeat(base + (j <= extra ? 1 : 0))}${w}`);\n  });\n}\nmodule.exports = { wrapText, justify };\n",
  "src/base64url.js": "// base64url (RFC 4648 section 5) in plain JavaScript: no Buffer, TextEncoder, atob or btoa\nconst ABC = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';\nfunction base64urlEncode(bytes) {\n  if (!Array.isArray(bytes) && Object.prototype.toString.call(bytes) !== '[object Uint8Array]') throw new TypeError('expected an array of bytes');\n  const b = Array.from(bytes);\n  for (const x of b) if (!Number.isInteger(x) || x < 0 || x > 255) throw new RangeError('invalid byte');\n  let out = '';\n  for (let i = 0; i < b.length; i += 3) {\n    const n = (b[i] << 16) | ((b[i + 1] ?? 0) << 8) | (b[i + 2] ?? 0); const k = Math.min(3, b.length - i) + 1;\n    for (let j = 0; j < k; j++) out += ABC[(n >> (18 - 6 * j)) & 63];\n  }\n  return out;\n}\nfunction utf8(s) {\n  const out = [];\n  for (let i = 0; i < s.length; i++) {\n    let c = s.charCodeAt(i);\n    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) { const d = s.charCodeAt(i + 1); if (d >= 0xdc00 && d <= 0xdfff) { c = 0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00); i++; } }\n    if (c >= 0xd800 && c <= 0xdfff) c = 0xfffd; // a lone surrogate\n    if (c < 0x80) out.push(c);\n    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));\n    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));\n    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));\n  }\n  return out;\n}\nfunction base64urlEncodeText(s) { if (typeof s !== 'string') throw new TypeError('expected a string'); return base64urlEncode(utf8(s)); }\nfunction base64urlDecode(s) {\n  if (typeof s !== 'string') throw new TypeError('expected a string');\n  const m = /^([A-Za-z0-9_-]*)(=*)$/.exec(s); const data = m ? m[1] : ''; const pad = m ? m[2].length : 0; const r = data.length % 4;\n  if (!m || r === 1 || (pad && (r === 0 || pad !== 4 - r))) throw new SyntaxError('invalid base64url');\n  const out = []; let acc = 0; let bits = 0;\n  for (const ch of data) { acc = (acc << 6) | ABC.indexOf(ch); bits += 6; if (bits >= 8) { bits -= 8; out.push((acc >> bits) & 255); acc &= (1 << bits) - 1; } }\n  if (acc !== 0) throw new SyntaxError('invalid base64url'); // the unused low bits of the last character must be zero\n  return new Uint8Array(out);\n}\nmodule.exports = { base64urlEncode, base64urlEncodeText, base64urlDecode };\n",
